import { NextResponse } from "next/server";
import fs from "fs";
import path from "path";
import { db } from "@/lib/mysql"; // adjust if needed
import { jwtVerify } from "jose";

const secret = new TextEncoder().encode(process.env.JWT_SECRET!);


export async function POST(req: Request) {
    try {
        const body = await req.json();
        const { name, email, mobile, message } = body;

        if (!name || !email || !mobile) {
            return NextResponse.json({ success: false });
        }

        try {
            // ✅ Try inserting into DB
            await db.execute(
                `INSERT INTO contact_requests (name, email, mobile, message)
         VALUES (?, ?, ?, ?)`,
                [name, email, mobile, message || null]
            );
        } catch (dbError: any) {
            console.error("DB FAILED — Writing to log file instead");

            // ✅ Fallback to file logging
            const logData = {
                name,
                email,
                mobile,
                message,
                created_at: new Date().toISOString(),
                error: dbError.message,
            };

            const logPath = path.join(process.cwd(), "contact_fallback.log");

            fs.appendFileSync(logPath, JSON.stringify(logData) + "\n");
        }

        // ✅ Always return success
        return NextResponse.json({ success: true });
    } catch (error: any) {
        console.error("contact API CRASH:", error);

        return NextResponse.json({ success: true });
    }
}
export async function GET(req: Request) {
    try {
        const cookie = req.headers.get("cookie");

        if (!cookie?.includes("admin_token=")) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const token = cookie
            .split(";")
            .find((c) => c.trim().startsWith("admin_token="))
            ?.split("=")[1];

        if (!token) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        await jwtVerify(token, secret);

        const [rows] = await db.query(
            `SELECT id, name, email, mobile, message, created_at
       FROM contact_requests
       ORDER BY created_at DESC`
        );

        return NextResponse.json(rows);
    } catch (error) {
        return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
}
